const $=s=>document.querySelector(s),key='frame-studio-v1',clone=o=>JSON.parse(JSON.stringify(o));
const sample={title:'雨夜来信',synopsis:'一封寄自十年前的信，让修复师林晚重新踏入即将拆除的老街。每逢雨夜，旧照相馆便会亮起灯，失踪多年的摄影师也再次出现。她循着照片背面的线索，发现那场意外背后，藏着一个所有人都在守护的秘密。',genre:'都市悬疑',style:'电影写实',ratio:'9:16 竖屏',episodes:6,duration:90,storyPrompt:'创作一部都市悬疑短剧，以雨夜和旧照片为线索，突出人物情感与每集结尾的悬念。',characters:[{name:'林晚',role:'女主角',description:'26 岁，旧照片修复师。沉静敏锐，深棕长发，米白风衣，内搭浅色衬衫。',prompt:'角色正面定妆照，26 岁亚洲女性，深棕长发，米白风衣，沉静坚定的眼神，自然柔光，纯色背景，电影质感，全身构图，保持面部清晰。',versions:[],confirmed:false,multi:[],multiPrompt:CharacterSheet.spec.prompt,view:'front'},{name:'陈默',role:'男主角',description:'30 岁，摄影师，黑色短发，深灰外套，寡言而温柔。',prompt:'亚洲男性摄影师正面全身定妆照，黑色短发，深灰外套，自然柔光，纯色背景，电影质感。',versions:[],confirmed:false,multi:[],view:'front'}],shots:[{title:'雨中的旧街',description:'雨水沿街边屋檐落下，林晚撑伞走向旧照相馆。',prompt:'远景，雨夜旧街，暖色橱窗与冷色雨幕，林晚穿米白风衣撑伞走近，缓慢推进。',versions:[]},{title:'一封迟到的信',description:'林晚打开泛黄的信封，看见十年前的邮戳。',prompt:'手部特写，泛黄信封，十年前的邮戳，柔和暖光，浅景深，镜头缓慢推近。',versions:[]},{title:'橱窗里的身影',description:'橱窗倒影中，一名陌生男子静静站在她身后。',prompt:'玻璃反射构图，雨滴与倒影，陈默出现在林晚身后，悬疑气氛，固定镜头。',versions:[]}],stages:{}};
let data;try{data=JSON.parse(localStorage.getItem(key))||clone(sample)}catch{data=clone(sample)}let tab=0,ci=0,si=0,timer;const tabs=['角色设计','场景设计','分镜脚本','画面生成','视频与配音','成片导出'];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(m){$('#toast').textContent=m;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function save(){try{localStorage.setItem(key,JSON.stringify(data));$('#saved').textContent='● 已保存到此浏览器'}catch{$('#saved').textContent='保存失败，请导出备份';toast('浏览器存储已满，请导出 JSON 备份')}}
function field(label,id,value,rows){return `<label>${label}${rows?`<textarea id="${id}" rows="${rows}">${esc(value)}</textarea>`:`<input id="${id}" value="${esc(value)}">`}</label>`}
function bind(id,obj,prop){$('#'+id).oninput=e=>{obj[prop]=e.target.value;save();if(prop==='name')overview()}}
function overview(){$('#storyTitle').textContent=data.title;$('#sideTitle').textContent=data.title;$('#synopsis').textContent=data.synopsis;$('#tags').innerHTML=[data.genre,data.style,data.ratio,`${data.episodes} 集短剧`].filter(Boolean).map(t=>`<span>${esc(t)}</span>`).join('');$('#duration').textContent=data.duration+' 秒';$('#charCount').textContent=data.characters.length;$('#shotCount').textContent=data.shots.length;$('#tabs').innerHTML=tabs.map((t,i)=>`<button data-tab="${i}" class="${tab===i?'selected':''}"><i>0${i+1}</i>${t}</button>`).join('');$('#tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{tab=+b.dataset.tab;render()})}
function portrait(angle=0,variant=0){return `<svg viewBox="0 0 260 330" aria-label="角色轮廓示意图" role="img"><defs><linearGradient id="coat${angle}" x2="1" y2="1"><stop stop-color="${variant%2?'#bab9a5':'#d8cfb8'}"/><stop offset="1" stop-color="#a5a28d"/></linearGradient></defs><ellipse cx="130" cy="318" rx="76" ry="8" fill="#b5c0a8" opacity=".5"/><path d="M95 145 Q67 157 64 202 L47 325H211L194 202Q190 158 163 145" fill="url(#coat${angle})"/><path d="M116 139h28l14 186h-57z" fill="#f1eada"/><path d="M101 150l-17 43 27-9-8 25 23 51-8-111M157 150l18 43-27-9 8 25-23 51 7-111" fill="#e2dbc8"/><path d="M93 88q-2-52 37-53 43 0 42 56l-1 73-28-19h-30l-25 20z" fill="#40473b"/><path d="M117 120h27v29q-13 20-27 0z" fill="#c4aa8c"/>${angle===2?'':`<ellipse cx="${angle===1?140:130}" cy="91" rx="${angle===1?20:29}" ry="39" fill="#d6bea0"/><path d="M98 82q-1-43 33-42 32 0 35 40-24-5-37-26-5 19-31 28" fill="#414638"/>${angle===1?'<path d="M155 88l7 12-8 3" fill="#c6aa8b"/>':'<path d="M112 90h8m20 0h8" stroke="#5e5c49" stroke-width="2"/><path d="M126 111q5 3 11-1" stroke="#ac8a73" fill="none"/>'}`}${angle===2?'<path d="M96 65q33-45 65 0l9 101q-42 22-79-1z" fill="#414638"/>':''}<path d="M76 204l-7 115m115-115 8 115M136 226v94" stroke="#989987" fill="none" stroke-width="1.5"/></svg>`}
function history(arr,active,handler){return arr.length?`<div class="history">${arr.map((v,i)=>`<button data-version="${i}" class="${active===i?'primary':''}">V${i+1} · ${esc(v.time)}</button>`).join('')}</div>`:'<p class="subtle">生成后会在这里保留历史版本。</p>'}
function newVersion(prompt){return{prompt,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),createdAt:Date.now()}}
function render(){overview();if(tab===0)characters();else if(tab===2)shots();else stage()}
function characters(){let c=data.characters[ci];if(!c){$('#panel').innerHTML='<div class="card empty-stage">还没有角色。<button id="add">＋ 添加角色</button></div>';$('#add').onclick=addChar;return}c.versions??=[];c.multi??=[];let multi=c.view==='multi';$('#panel').innerHTML=`<div class="section-head"><div><h3>先认识，你的故事主角</h3><p>从一张正面图开始，让每一个角度都保持一致。</p></div><button id="add">＋ 添加角色</button></div><div class="editor"><div class="card"><div class="mini-label">角色库 / ${String(data.characters.length).padStart(2,'0')}</div><div class="character-list">${data.characters.map((v,i)=>`<button class="character-item ${i===ci?'selected':''}" data-char="${i}"><span class="initial">${esc(v.name?.[0]||'角')}</span><div>${esc(v.name)}<small>${esc(v.role)} · ${v.confirmed?'已确认':'待确认'}</small></div></button>`).join('')}</div><div class="divider"></div><p class="subtle">01 生成正面形象<br>02 确认角色版本<br>03 扩展多面视图</p></div><div class="card"><div class="preview-head"><span>形象预览 <span class="status"> / ${c.confirmed?'已确认':'待确认'}</span></span><div class="view-toggle"><button id="front" class="${multi?'':'selected'}">正面图</button><button id="multi" class="${multi?'selected':''}">多面图</button></div></div><div class="artboard"><span class="watermark">${(multi?c.multi:c.versions).length?'演示生成':'示意预览'} · 非 AI 图像</span>${multi?c.multi.length?`<div class="angle-grid">${['正面','左侧面','背面','¾ 侧面'].map((a,i)=>`<div class="angle">${portrait(i,c.active||0)}<span>${a}</span></div>`).join('')}</div>`:'<div class="empty-stage">◈<p>确认正面形象后<br>生成角色多面图</p></div>':portrait(0,c.active||0)}<span class="art-label">${esc(c.name)} / CHARACTER ${multi?'SHEET':'FRONT'}</span></div><div class="preview-actions"><button id="confirm" ${!c.versions.length?'disabled':''}>${c.confirmed?'✓ 已确认正面形象':'✓ 确认正面形象'}</button><button id="makeMulti" ${!c.confirmed?'disabled':''}>◈ 生成多面图</button></div><p class="subtle">${c.stale?'正面形象已更换，已有多面图待更新。':'多面图将沿用已确认正面图的外貌与服装设定。'}</p><div class="divider"></div><div class="mini-label">${multi?'多面图':'正面图'}历史版本 · 点击采用</div>${history(multi?c.multi:c.versions,multi?c.multiActive:c.active)}</div><div class="card"><div class="right-title">角色设定</div><div class="field-row">${field('姓名','charName',c.name)}${field('角色身份','charRole',c.role)}</div>${field('外貌与性格','charDesc',c.description,3)}<div class="divider"></div><div class="right-title flex">${multi?'多面图':'正面图'}提示词<button class="text" id="resetPrompt">恢复默认</button></div>${field('可自由编辑 · 修改后自动保存','charPrompt',multi?c.multiPrompt||'':c.prompt,6)}<button class="primary wide" id="generate">✦ ${multi?'演示生成多面图':'演示生成正面图'}</button><p class="subtle">当前为流程演示，保留提示词和版本记录；实际 AI 生成服务尚未接入。</p></div></div>`;
$('#add').onclick=addChar;document.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{ci=+b.dataset.char;render()});bind('charName',c,'name');bind('charRole',c,'role');bind('charDesc',c,'description');bind('charPrompt',c,multi?'multiPrompt':'prompt');$('#front').onclick=()=>{c.view='front';save();render()};$('#multi').onclick=()=>{c.view='multi';save();render()};$('#resetPrompt').onclick=()=>{c[multi?'multiPrompt':'prompt']=multi?sample.characters[0].multiPrompt:`${c.description}，正面全身定妆照，纯色背景，柔和自然光，保持面部清晰。`;save();render()};$('#generate').onclick=()=>generateCharacter(multi);$('#confirm').onclick=()=>{c.confirmed=true;save();render();toast('已确认正面形象，可生成多面图')};$('#makeMulti').onclick=()=>{c.view='multi';generateCharacter(true)};document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{if(multi)c.multiActive=+b.dataset.version;else{c.active=+b.dataset.version;c.confirmed=false;if(c.multi.length)c.stale=true}save();render()})}
function addChar(){data.characters.push({name:'新角色',role:'配角',description:'',prompt:'角色正面全身定妆照，纯色背景，自然柔光。',multiPrompt:sample.characters[0].multiPrompt,versions:[],multi:[],confirmed:false});ci=data.characters.length-1;save();render()}
function generateCharacter(multi){const c=data.characters[ci];if(multi&&!c.confirmed){toast('请先生成并确认正面形象');return}let arr=multi?c.multi:c.versions;arr.push(newVersion(multi?c.multiPrompt:c.prompt));if(multi){c.multiActive=arr.length-1;c.stale=false}else{c.active=arr.length-1;c.confirmed=false;if(c.multi.length)c.stale=true}save();render();toast('演示版本已生成，提示词与版本已保存')}
function shots(){let s=data.shots[si];$('#panel').innerHTML=`<div class="section-head"><div><h3>把故事，拆成每一个镜头</h3><p>逐镜编辑画面、动作与提示词，保留每一次尝试。</p></div><button id="addShot">＋ 添加分镜</button></div><div class="editor"><div class="card shot-list"><div class="mini-label">分镜列表 / 第 1 集</div>${data.shots.map((s,i)=>`<button data-shot="${i}" class="${si===i?'primary':''}">0${i+1}　${esc(s.title)}</button>`).join('')}</div>${s?`<div class="card"><div class="preview-head">镜头 ${String(si+1).padStart(2,'0')}<span class="status">${s.versions.length?'已有演示版本':'待生成'}</span></div><div class="artboard" style="background:linear-gradient(155deg,#344940,#9ca68b)"><div class="empty-stage" style="color:white"><div class="stage-icon">▧</div><h3>${esc(s.title)}</h3><p>分镜画面预览区域</p><small>流程演示 · 未接入图像生成</small></div></div><p id="shotDescPreview">${esc(s.description)}</p>${history(s.versions,s.active)}</div><div class="card"><div class="right-title">镜头设定</div>${field('镜头名称','shotTitle',s.title)}${field('画面描述','shotDesc',s.description,3)}${field('分镜提示词','shotPrompt',s.prompt,6)}<button id="shotGen" class="primary wide">✦ 演示重新生成</button></div>`:'<div class="card empty-stage">添加第一个分镜，开始拆解故事。</div>'}</div>`;$('#addShot').onclick=()=>{data.shots.push({title:'新镜头',description:'',prompt:'',versions:[]});si=data.shots.length-1;save();render()};document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>{si=+b.dataset.shot;render()});if(s){bind('shotTitle',s,'title');bind('shotDesc',s,'description');bind('shotPrompt',s,'prompt');$('#shotGen').onclick=()=>{s.versions.push(newVersion(s.prompt));s.active=s.versions.length-1;save();render();toast('分镜演示版本已保存')};document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{s.active=+b.dataset.version;s.prompt=s.versions[s.active].prompt;save();render()})}}
function stage(){let state=data.stages[tab]??={prompt:({1:'雨夜的老街照相馆，木质门框，暖黄色灯光，雨水反光，保持跨镜头场景一致。',3:'沿用已确认角色与场景，为每个分镜生成风格统一的关键帧。',4:'根据分镜生成流畅视频，中文自然对白，轻微雨声，控制背景音乐音量。',5:'按分镜顺序剪辑，9:16 竖屏，1080p，统一字幕样式。'})[tab],versions:[]};$('#panel').innerHTML=`<div class="section-head"><div><h3>${['','让故事有一个发生的地方','','为每个镜头定格关键画面','让画面与声音一起讲故事','你的故事，即将成为作品'][tab]}</h3><p>提示词可修改，版本持续保留。</p></div></div><div class="stage-grid"><div class="card empty-stage"><div class="stage-icon">${['','⌂','','▧','▷','▣'][tab]}</div><h3>${tabs[tab]}</h3><p>${state.versions.length?'已创建 '+state.versions.length+' 个演示版本':'准备好设定，开始下一步创作'}</p><p class="subtle">当前展示制作流程，实际生成与成片渲染尚未接入。</p>${history(state.versions,state.active)}</div><div class="card"><div class="right-title">${tabs[tab]}提示词</div>${field('输入你的创作要求','stagePrompt',state.prompt,9)}<button class="primary wide" id="stageGen">✦ ${state.versions.length?'演示重新生成':'创建演示版本'}</button><p class="subtle">每次生成记录当前提示词。项目 JSON 导出包含所有编辑与历史版本。</p></div></div>`;bind('stagePrompt',state,'prompt');$('#stageGen').onclick=()=>{state.versions.push(newVersion(state.prompt));state.active=state.versions.length-1;save();render();toast('演示版本已保存')};document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{state.active=+b.dataset.version;state.prompt=state.versions[state.active].prompt;save();render()})}
function normalize(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('JSON 顶层需要是一个项目对象');let r=raw.project||raw;let characters=r.characters||r.roles||[],shots=r.shots||r.storyboards||[];if(!Array.isArray(characters)||!Array.isArray(shots))throw Error('characters 和 shots 需要是数组');return{...clone(sample),...r,title:String(r.title||r.name||'未命名短剧'),synopsis:String(r.synopsis||r.summary||r.description||''),characters:characters.map((c,i)=>({name:typeof c==='string'?c:c.name||`角色 ${i+1}`,role:'配角',description:'',prompt:'角色正面定妆照，纯色背景，自然柔光。',multiPrompt:sample.characters[0].multiPrompt,versions:[],multi:[],confirmed:false,...(typeof c==='object'?c:{})})),shots:shots.map((s,i)=>({title:typeof s==='string'?s:s.title||`镜头 ${i+1}`,description:'',prompt:'',versions:[],...(typeof s==='object'?s:{})})),stages:r.stages||{}}}
function importProject(r){data=normalize(r);ci=si=tab=0;save();render();$('#importDialog').close();toast('项目导入成功，已自动保存')}
function openImport(){$('#importError').textContent='';$('#importDialog').showModal()}
['#import','#importSide'].forEach(s=>$(s).onclick=openImport);$('#parse').onclick=()=>{try{importProject(JSON.parse($('#jsonInput').value))}catch(e){$('#importError').textContent='导入失败：'+e.message}};$('#sample').onclick=()=>importProject(clone(sample));async function readFile(f){if(!f)return;try{$('#jsonInput').value=await f.text();$('#importError').textContent='文件已读取，点击「导入项目」确认。'}catch{$('#importError').textContent='无法读取文件'}}$('#file').onchange=e=>readFile(e.target.files[0]);$('#drop').ondragover=e=>e.preventDefault();$('#drop').ondrop=e=>{e.preventDefault();readFile(e.dataTransfer.files[0])};
function exportProject(){save();let b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=data.title+'-项目.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('项目 JSON 已导出')};['#export','#exportSide'].forEach(s=>$(s).onclick=exportProject);$('#save').onclick=()=>{save();toast('已保存到当前浏览器，可导出 JSON 备份')};
$('#editStory').onclick=()=>{$('#titleInput').value=data.title;$('#synopsisInput').value=data.synopsis;$('#storyPrompt').value=data.storyPrompt||'';$('#storyHistory').innerHTML=history(data.storyVersions||[],data.storyActive);$('#storyHistory').querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>{let v=data.storyVersions[+b.dataset.version];data.title=v.title;data.synopsis=v.synopsis;data.storyPrompt=v.prompt;data.storyActive=+b.dataset.version;save();overview();$('#editStory').click()});$('#storyDialog').showModal()};[['#titleInput','title'],['#synopsisInput','synopsis'],['#storyPrompt','storyPrompt']].forEach(([s,p])=>$(s).oninput=e=>{data[p]=e.target.value;save();overview()});$('#storyGen').onclick=()=>{data.storyVersions??=[];data.storyVersions.push({...newVersion(data.storyPrompt),title:data.title,synopsis:data.synopsis});save();toast('已保存剧情快照；AI 剧情生成待接入')};window.addEventListener('beforeunload',save);render();save();

// Local ComfyUI connection. Generation awaits the user's API workflow.
const comfyButton=document.createElement('button');comfyButton.textContent='⚙ ComfyUI';document.querySelector('.header-actions').prepend(comfyButton);
const comfyDialog=document.createElement('dialog');comfyDialog.innerHTML='<div class="modal-head"><h2>本地 ComfyUI</h2><button id="comfyClose">✕</button></div><p>通过本地服务连接 ComfyUI，生成任务在你的电脑运行。</p><label>本机 ComfyUI 端口<input id="comfyPort" type="number" min="1" max="65535"></label><p id="comfyStatus">尚未测试连接</p><div class="modal-actions"><button class="primary" id="comfyTest">测试连接</button></div><p class="subtle">下一步需要导入 ComfyUI 的 API 格式工作流，并关联提示词、参考图和输出节点。</p>';document.body.append(comfyDialog);
comfyButton.onclick=()=>{document.querySelector('#comfyPort').value=localStorage.getItem('frame-comfy-port')||'8188';comfyDialog.showModal()};document.querySelector('#comfyClose').onclick=()=>comfyDialog.close();document.querySelector('#comfyPort').oninput=e=>localStorage.setItem('frame-comfy-port',e.target.value);
document.querySelector('#comfyTest').onclick=async()=>{const status=document.querySelector('#comfyStatus'),port=document.querySelector('#comfyPort').value;status.textContent='正在连接本机 ComfyUI…';try{if(location.protocol==='file:')throw Error('请使用本地启动入口打开工作台。');const r=await fetch('/api/comfy/system_stats?port='+encodeURIComponent(port));const info=await r.json();if(!r.ok)throw Error(info.error||'连接失败');status.textContent='连接成功 · '+(info.devices?.map(d=>d.name).join(' / ')||'ComfyUI 已就绪');localStorage.setItem('frame-comfy-port',port)}catch(e){status.textContent=e.message}};
